#define I2C_OP_Count(ubGroupsel)                   (SYS1B_I2C_GP1_OP_CNT + (ubGroupsel-1)*(0x20>>2))
#define I2C_NACK(ubGroupsel)                       (SYS1L_I2C_GP1_NACK + (ubGroupsel-1)*(0x20>>2))
#define I2C_CLK_DIV_CNT(ubGroupsel,val)            (SYS1B[SYS1L_I2C_GP1_CLK_DIV_CNT+ (ubGroupsel-1)*(0x20>>2)] = (unsigned char)(val))



