/////////////////////   RTT
#define RTT_SCALE_33NS      0
#define RTT_SCALE_100NS     1
#define RTT_SCALE_1US       2
#define RTT_SCALE_1MS       3  

#define SYS1L_RTT_CTRL                (0x600>>2)
#define SYS1B_RTT1_CTRL                (0x600)
#define SYS1B_RTT2_CTRL                (0x601)
	#define SYS_RTTAURST           BIT6        //RTT auto reset               0:auto reset,   1:stop   	(0)
    	#define SYS_RTTEN              BIT7        //enable RTT timer             0:Disable,      1:Enable 	(0)
	#define SYS_CNT_CLEAR          BIT4        //counter clear
        #define SYS_RTT_SCALE          BIT0        //scale =0: 33.33ns ; 1=100ns; 2=1us; 3=1ms
#define SYS1L_COMB_CTRL               (0x604>>2)
        #define SYS_RTT_COMBINE        BIT5       //1= 把 RTT1 跟 RTT2 結合成一個 RTT1, (bit 數從原來的 兩個 32bit 變成一個 64 bit 的 counter)
        
        
#define SYS1L_RT1_TO_LIMIT                 (0x610>>2)
#define SYS1L_RT2_TO_LIMIT                 (0x614>>2)

#define SYS1L_RT1_CNT                 (0x620>>2)
#define SYS1L_RT2_CNT                 (0x624>>2)



#define RTT_Set_Limit(rtt_sel, val)		(SYS1L[SYS1L_RTTSR( (rtt_sel) )] = (unsigned long)(val) )
#define RTT_Get_Limit(rtt_sel)		    (SYS1L[SYS1L_RTTSR( (rtt_sel) )])
#define SYS1L_RTTSR(N)	                (SYS1L_RT1_TO_LIMIT+(N-1))

#define RTT_Set_Value(rtt_sel, val)		(SYS1L[SYS1L_RTTCNT( (rtt_sel) )] = (unsigned long)(val) )
#define RTT_Get_Value(rtt_sel)		(SYS1L[SYS1L_RTTCNT( (rtt_sel) )])
#define SYS1L_RTTCNT(N)                  (SYS1L_RT1_CNT+(N-1))

#if(!RDT)
#define RTT1_Stop()			(SYS1L[SYS1L_RTT_CTRL] = (SYS1L[SYS1L_RTT_CTRL] & (~SYS_RTTEN)) | SYS_CNT_CLEAR)
#define RTT1_Start()			(SYS1L[SYS1L_RTT_CTRL] |= SYS_RTTEN)
#endif
