/////////////////// Uart
#define UART_Reg_STARTADDRESS 0x04003200
#define UARTO    	((volatile unsigned long long *)UART_Reg_STARTADDRESS)
#define UARTW        	((volatile unsigned short *)UART_Reg_STARTADDRESS)
#define UARTB        	((volatile unsigned char *)UART_Reg_STARTADDRESS)
#define UARTL        	((volatile unsigned long *)UART_Reg_STARTADDRESS)

        #define UARTL_UART_CTRL         (0x00>>2)
                #define CLR_BAUD_RATE           0xFF000000
                #define BAUD_RATE(x)		((unsigned long )x&0x00FFFFFF)
				#define OOB_EN                  BIT24
				#define RX_RST          		BIT31
		#define UARTL_UART_TRIG         ((0x04)>>2)
				#define OOB_RX_BUF_NOT_EMPTY	BIT8
				#define TX_TRIG         		BIT0
        #define UARTL_TX_PKT_CFG		((0x0C)>>2)
                #define TX_PKT_TYP(x)		((unsigned char )x&0xFF)			
                #define TX_PAYLOAD_LEN(x)	(((unsigned short )x<<8)&0xFF00)
		#define UARTB_TX_PAYLOAD_LEN	((0x0D)>>0)
		#define UARTB_TX_PAYLOAD         (0x10)
		#define UARTLL_TX_PAYLOAD               (0x10 >> 3)
        #define UARTL_OOB_UR_INT_EN             ((0x50)>>2)
//                #define TX_CMPLT_INT_EN           0x800
		#define UARTL_OOB_Receive_Packet_INFO	(0x54 >> 2)
		#define UARTB_OOB_RX_Payload	        (0x60 >> 0)
		#define UARTLL_OOB_RX_Payload	        (0x60 >> 3)
		#define	UARTL_UR_INT_STATUS			    (0x70 >> 2)
		#define UARTL_RX_FIFO_DATA              ((0x58)>>2)
				#define RX_FIFO_EMPTY	         BIT8
        #define UARTB_SERIAL_DATA               (0x74)
        #define UARTL_S_FIFO_CTLST              (0x78>>2)
        #define TX_SERIAL_FIFO_EN               BIT8
        #define S_FIFO_EMPTY                    BIT1
        #define S_FIFO_FULL                      BIT0

                
		#define PKT_CRC_ERR_INT_EN        BIT0
