#define SPIL_CFG			(0x00>>2)
	#define Dummy_Byte_Enable					BIT8
	#define SPI_BUF_MODE							BIT7
	#define SPI_CS_N_output_value				BIT6
	#define SPI_CS_N_Switch						BIT5 // 0: Control by IP   1: Control by FW  default(0)
	#define DMA_read_write_direction			BIT0 // 0: spi read   1: spi write  default(0)


#define SPIL_START_ADD			(0x04>>2)
	#define SPI_Start_Address_Register_SET(X)	(SPIL[SPIL_START_ADD] = (X & 0x00FFFFFF))


#define SPIL_DMA_BCNT			(0x08>>2)
	// Clock Cycle Count
	#define SPI_DMA_Byte_Counts_SET(X)			(SPIL[SPIL_DMA_BCNT] = (X & 0x00FFFFFF))


#define SPIL_PAGE_SIZE			(0x0C>>2)
	#define SPI_Page_Size_SET(X)				(SPIL[SPIL_PAGE_SIZE] = (X & 0x00000FFF))


#define SPIL_DMA_RAM_ADDR		(0x10>>2)
	#define SPI_DMA_RAM_Address_SET(X)			(SPIL[SPIL_DMA_RAM_ADDR] = (X & 0x00000FFF))


#define SPIL_CMD_LEN			(0x14>>2)
	#define SPI_Start_Address_Length_SET(X)		(SPIL[SPIL_CMD_LEN] |= ((X << 16) & 0x000F0000))
	#define SPI_Command_4_Length_SET(X)			(SPIL[SPIL_CMD_LEN] |= ((X << 12) & 0x0000F000))
	#define SPI_Command_3_Length_SET(X)			(SPIL[SPIL_CMD_LEN] |= ((X << 8) & 0x00000F00))
	#define SPI_Command_2_Length_SET(X)			(SPIL[SPIL_CMD_LEN] |= ((X << 4) & 0x000000F0))
	#define SPI_Command_1_Length_SET(X)			(SPIL[SPIL_CMD_LEN] |= ((X << 0) & 0x0000000F))


#define SPIL_CMD_1			(0x18>>2)
#define SPIL_CMD_2			(0x1C>>2)
#define SPIL_CMD_3			(0x20>>2)
#define SPIL_CMD_4			(0x24>>2)
#define SPIL_CMD_8765			(0x28>>2)
	#define SPI_Command_8_SET(X)				(SPIL[SPIL_CMD_8765] |= ((X << 24) & 0xFF000000))
	#define SPI_Command_7_SET(X)				(SPIL[SPIL_CMD_8765] |= ((X << 16) & 0x00FF0000))
	#define SPI_Command_6_SET(X)				(SPIL[SPIL_CMD_8765] |= ((X << 8) & 0x0000FF00))
	#define SPI_Command_5_SET(X)				(SPIL[SPIL_CMD_8765] |= ((X << 0) & 0x000000FF))


#define SPIL_CMD_ORDER_L		(0x2C>>2)
	#define SPI_Command_Order_8_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0x0FFFFFFF))
	#define SPI_Command_Order_7_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xF0FFFFFF))
	#define SPI_Command_Order_6_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFF0FFFFF))
	#define SPI_Command_Order_5_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFFF0FFFF))
	#define SPI_Command_Order_4_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFFFF0FFF))
	#define SPI_Command_Order_3_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFFFFF0FF))
	#define SPI_Command_Order_2_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFFFFFF0F))
	#define SPI_Command_Order_1_CLEAR()			(SPIL[SPIL_CMD_ORDER_L] &= (0xFFFFFFF0))

	#define SPI_Command_Order_8_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 28) & 0xF0000000))
	#define SPI_Command_Order_7_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 24) & 0x0F000000))
	#define SPI_Command_Order_6_SET(X)          		(SPIL[SPIL_CMD_ORDER_L] |= ((X << 20) & 0x00F00000))
	#define SPI_Command_Order_5_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 16) & 0x000F0000))
	#define SPI_Command_Order_4_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 12) & 0x0000F000))
	#define SPI_Command_Order_3_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 8) & 0x00000F00))
	#define SPI_Command_Order_2_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 4) & 0x000000F0))
	#define SPI_Command_Order_1_SET(X)			(SPIL[SPIL_CMD_ORDER_L] |= ((X << 0) & 0x0000000F))


#define SPIL_CMD_ORDER_H		(0x30>>2)
