	#define SPI_Command_Order_16_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 28) & 0xF0000000))
	#define SPI_Command_Order_15_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 24) & 0x0F000000))
	#define SPI_Command_Order_14_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 20) & 0x00F00000))
	#define SPI_Command_Order_13_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 16) & 0x000F0000))
	#define SPI_Command_Order_12_SET(X) 		(SPIL[SPIL_CMD_ORDER_H] |= ((X << 12) & 0x0000F000))
