	#define SPI_Command_Order_10_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 4) & 0x000000F0))
	#define SPI_Command_Order_9_SET(X)			(SPIL[SPIL_CMD_ORDER_H] |= ((X << 0) & 0x0000000F))

#define SPIL_TRIG					(0x34>>2)
