	#define SPI_Read_Data_byte3_SET(X)			(SPIL[SPIL_RDATA0] |= ((X << 24) & 0xFF000000))
	#define SPI_Read_Data_byte2_SET(X)			(SPIL[SPIL_RDATA0] |= ((X << 16) & 0x00FF0000))
	#define SPI_Read_Data_byte1_SET(X)			(SPIL[SPIL_RDATA0] |= ((X << 8) & 0x0000FF00))
	#define SPI_Read_Data_byte0_SET(X)			(SPIL[SPIL_RDATA0] |= ((X << 0) & 0x000000FF))

