	#define SPI_Read_Data_byte7_SET(X)			(SPIL[SPIL_RDATA1] |= ((X << 24) & 0xFF000000))
	#define SPI_Read_Data_byte6_SET(X)			(SPIL[SPIL_RDATA1] |= ((X << 16) & 0x00FF0000))
	#define SPI_Read_Data_byte5_SET(X)			(SPIL[SPIL_RDATA1] |= ((X << 8) & 0x0000FF00))
	#define SPI_Read_Data_byte4_SET(X)			(SPIL[SPIL_RDATA1] |= ((X << 0) & 0x000000FF))






