#define HB_DEVICE									0x12
	// 7.61.3.2 Forced Unit Access (FUA)
	//	When the FUA bit is set to one regardless of whether volatile and/or non-volatile write caching in the device is enabled or not, 
	//	the user data shall be written to non-volatile media before command completion is reported.
	//	When the FUA bit is cleared to zero the device may return command completion before the data is written to the non-volatile media.
	#define 	CHK_FUA 								CHK_BIT7	// Set Forced Unit Access (FUA) 

   
#define HB_COMMAND    	 								0x13

#define HB_STATUS     									0x14			
	#define 	SET_ICRC        								SET_BIT7    // Set Bad BlocK detected
	#define 	SET_BBK									SET_BIT7	// Set Bad BlocK detected
	#define 	SET_UNC									SET_BIT6	// Set UN-Correctable data
	#define 	SET_WP      									SET_BIT6    // Set write protect for write cmd
	#define 	SET_MC									SET_BIT5	// Set Media Changed
	#define 	SET_IDNF									SET_BIT4	// ID Not Found
	#define 	SET_MCR									SET_BIT3	// Media Changed Requested
	#define 	SET_ABRT									SET_BIT2	// ABoRTed command
	#define 	SET_TK0NF									SET_BIT1	// TracK 0 Not Found
	#define 	SET_AMNF									SET_BIT0	// Address Mark Not Found
	#define 	SET_ERR		    							SET_BIT0	// Set	 ATA Command Error

#define HB_ERROR										0x15		
