	#define 	SET_ICRC            								SET_BIT7    // Set Bad BlocK detected
	#define 	SET_BBK            							 	SET_BIT7    // Set Bad BlocK detected
	#define 	SET_UNC             								SET_BIT6    // Set UN-Correctable data
	#define 	SET_WP              								SET_BIT6    // Set write protect for write cmd
	#define 	SET_MC              								SET_BIT5    // Set Media Changed
	#define 	SET_IDNF            								SET_BIT4    // ID Not Found
	#define 	SET_MCR             								SET_BIT3    // Media Changed Requested
	#define 	SET_ABRT            								SET_BIT2    // ABoRTed command
	#define 	SET_TK0NF           								SET_BIT1    // TracK 0 Not Found
	#define 	SET_AMNF            								SET_BIT0    // Address Mark Not Found

