//===================================================
//	PS3111 DMAC & SS & SATA Doorbell Define
//===================================================
#define DCCM0_BANK0_STARADDRESS 0x5C0C0000
#define DCCM0_BANK1_STARADDRESS 0x5C0C8000
#define DCCM1_BANK0_STARADDRESS 0x5C0D0000
#define DCCM1_BANK1_STARADDRESS 0x5C0D4000

#define SEB	((volatile unsigned char * ) (DCCM0_BANK0_STARADDRESS))
#define SEL	((volatile unsigned long * ) (DCCM0_BANK0_STARADDRESS))
#define DMACB	((volatile unsigned char * ) (DCCM0_BANK0_STARADDRESS))
#define DMACL	((volatile unsigned long * ) (DCCM0_BANK0_STARADDRESS))
#define DCCMSATAB	((volatile unsigned char * ) (DCCM0_BANK0_STARADDRESS))
#define DCCMSATAL	((volatile unsigned long * ) (DCCM0_BANK0_STARADDRESS))

#define DCCM0_BANK0_BASE_BYTE ((volatile unsigned char *)DCCM0_BANK0_STARADDRESS)
#define DCCM0_BANK0_BASE_LONG ((volatile unsigned long *)DCCM0_BANK0_STARADDRESS)
#if RDT
#define TxMainStackSize 3072
#define TxFTLStackSize		1536//2816
#define TxFLAStackSize		1536
#else
#define TxMainStackSize	1696//1792 // PPS test pettern will hit stack overflow while CMD RW w/o retry
#define TxFTLStackSize		2912//2816 //SVN2213左右把所有組態的stack配置都跟上TSB TLC, 避免main爆stack
#define TxFLAStackSize		2048
#endif
#define TxTotalStackSize		(TxMainStackSize + TxFTLStackSize + TxFLAStackSize)	// total 5k
#define TxThreadStackArea0 	DCCM0_BANK1_STARADDRESS
#define TxThreadStackArea1	(TxThreadStackArea0 + TxMainStackSize)
#define TxThreadStackArea2 	(TxThreadStackArea1 + TxFTLStackSize)

//============================================
//DMAC	SQ : 		16 * 32
//DMAC	CQ : 		16 * 8 
//SS     	SQ : 		4 * 32
//SS     	CQ : 		4 * 32
//SATA  	Done Tag : 	1 * 128
//SATA  	Zinfo : 	1 * 64
//Flash	Message : 	1 * 512
//============================================
#define 	MaxSQCnt_SE 	4
#define 	MaxCQCnt_SE 	4
#define 	MaxSQBUF 	(MaxSQCnt_SE*8)
#define 	MaxSQBUFMASK 	(MaxSQBUF-1)
#define 	MaxCQBUF 	(MaxCQCnt_SE*8)
#define 	MaxCQBUFMASK 	(MaxCQBUF-1)

#define 	MaxSQCnt_DMAC 	16
#define 	MaxCQCnt_DMAC 	16

#define 	MaxQLength_SATA 128
#define	Spare4kSize		16
#define	Spare16kSize	(Spare4kSize*4)

#define DOOR_BELL_STARTADDRESS 	(DCCM0_BANK1_STARADDRESS + TxTotalStackSize)
#define Quue_Addr_DMAC_SQ 		DOOR_BELL_STARTADDRESS
#define Quue_Addr_DMAC_CQ 		(Quue_Addr_DMAC_SQ + (32 * MaxSQCnt_DMAC))
#define Quue_Addr_SS_SQ 		(Quue_Addr_DMAC_CQ + (8 * MaxCQCnt_DMAC))
#define Quue_Addr_SS_CQ 		(Quue_Addr_SS_SQ + (32 * MaxSQCnt_SE))
#define Quue_Addr_SATA_DoneTag 	(Quue_Addr_SS_CQ + (32 * MaxCQCnt_SE))
#define Quue_Addr_SATA_Zinfo 		(Quue_Addr_SATA_DoneTag + MaxQLength_SATA)
#define Quue_Addr_FLH 			(Quue_Addr_SATA_Zinfo + 64 + 16) // 64byte zinfo + 4byte msg_type3  //+4 好難數喔
// Flash INTTable總共512B. door bell總共佔了1616Byte
#define DMACL_SQBaseAddr ((volatile unsigned long *)Quue_Addr_DMAC_SQ) 
#define DMACB_CQBaseAddr ((volatile unsigned char *)Quue_Addr_DMAC_CQ) 
#define DMACL_CQBaseAddr ((volatile unsigned long *)Quue_Addr_DMAC_CQ) 
#define SEL_SQBaseAddr ((volatile unsigned long *)Quue_Addr_SS_SQ) 
#define SEL_CQBaseAddr ((volatile unsigned long *)Quue_Addr_SS_CQ) 

#define SEB_SQ_WPIU 	(0x4C) 
#define SEB_CQ_RPIU 	(0x70) 
#define SEB_SQ_CTRL 	(0x57) 
#define SEB_CQ_CTRL 	(0x77) 
#define SEB_SQ_WR_CNT 	(0x4e) 
#define SEB_CQ_RD_CNT 	(0x72) 

#define DMACB_SQ_WPIU 	(0x0C) 
#define DMACB_CQ_RPIU 	(0x30) 
#define DMACB_SQ_CTRL 	(0x17) 
#define DMACB_CQ_CTRL 	(0x37) 
#define DMACB_SQ_WR_CNT 	(0x0e) 
#define DMACB_CQ_RD_CNT 	(0x32) 

#define SATAL_DONETAG 	(0xC8>>2)
#define SATAB_WPIU	(0xCC) 
#define SATAB_RPIU 	(0xD0) 
#define SATAB_CTRL	(0xD7) 
#define SATAB_WR_CNT 	(0xCE) 
#define SATAB_RD_CNT 	(0xD2) 

#define DONETAG_PTR ((volatile unsigned long *)(DCCM0_BANK0_STARADDRESS+0xC8)) 
#define DONETAG ((volatile unsigned char *)*DONETAG_PTR) 

#define ACCL_BaseAddr ((volatile unsigned long *)(DCCM0_BANK0_STARADDRESS + 0x210)) 
#define ACCB_BaseAddr ((volatile unsigned char *)(DCCM0_BANK0_STARADDRESS + 0x210)) 

#define ACC_L2P	0
#define ACC_PCA	(0x4>>2)
#define ACC_OFFSET	(0x8)
#define ACC_LENGTH	(0x9)
#define ACC_MODE		(0xA)
#define ACC_MASK		(0xB)
#define ACC_ZIPMAP	(0xC>>2)

